import React from "react";
import { Link } from "react-router-dom";
import { FaUser, FaSearch } from "react-icons/fa";
import "./Admin.css";

export default function AdminNavbar({ search, setSearch }) {
  return (
    <div className="nav-outer">
      <div className="nav-inner">
        
        <Link to="/admin/products" className="logo">
          <span>e</span>Store Admin
        </Link>

        <ul className="nav-links">
          <li><Link to="/admin/products">PRODUCT LIST</Link></li>
          <li><Link to="/admin/products/add">ADD PRODUCT</Link></li>
        </ul>

        <div className="nav-right">
          <div className="search-pill">
            <input
              type="text"
              placeholder="Search products..."
              value={search}
              onChange={(e) => setSearch(e.target.value)}
            />
          </div>

          <Link to="/admin/account" className="icon-circle">
            <FaUser />
          </Link>
        </div>

      </div>
    </div>
  );
}
